  -h, --help
          Print help
  -V, --version
          Print version
'''

class Config:
    def __init__(self):
        self.message_keys=['short_message','msg','message']
        self.time_keys=['timestamp','time','@timestamp']
        self.dump_all_exclude=[]
        self.always_print_fields=[]
        self.level_keys=['level','severity','log.level','loglevel']
        self.main_line_format=DEFAULT_MAIN
        self.additional_value_format=DEFAULT_ADD
        self.level_map={}

class Opts:
    def __init__(self):
        self.additional=[]; self.cli_msg=[]; self.cli_time=[]; self.cli_level=[]
        self.config_file=None; self.print_lua=False; self.map_levels=[]
        self.dump_all=False; self.excluded=[]; self.with_prefix=False
        self.filter_expr=None; self.no_implicit=False; self.main_fmt=None; self.add_fmt=None
        self.substitute=False; self.context_key='context'; self.placeholder_format='{key}'
        self.input='-'

# ---------- ANSI/style helpers ----------
def bold(s): return f'{ESC}1m{s}{RESET}'
def dim(s): return f'{ESC}2m{s}{RESET}'
def fg(code, s): return f'{ESC}{code}m{s}{RESET}'
def rgb(r,g,b,s): return f'{ESC}38;2;{r};{g};{b}m{s}{RESET}'
def red_prefix(): return f'{ESC}1;31m??? >{RESET}'
def orange_prefix(): return f'{ESC}1;38;2;255;135;22m??? >{RESET}'

def level_color_name(level):
    l=str(level).lower()
    if l=='info': return '32'
    if l=='debug': return '34'
    if l=='warn': return '33'
    if l=='error': return '31'
    if l=='trace': return '36'
    return '35'

def level_style_text(text, raw_level):
    return f'{ESC}1;{level_color_name(raw_level)}m{text}{RESET}'

# ---------- CLI ----------
def clap_err(msg, tip=None):
    sys.stderr.write(f'error: {msg}\n\n')
    if tip:
        sys.stderr.write(f'  tip: {tip}\n\n')
    sys.stderr.write('Usage: executable [OPTIONS] [INPUT]\n\nFor more information, try \'--help\'.\n')
    return 2

def parse_args(argv):
    o=Opts(); pos=[]; i=0
    need={
        '-a':'additional','--additional-value':'additional',
        '--config-file':'config_file','-m':'cli_msg','--message-key':'cli_msg',
        '-t':'cli_time','--time-key':'cli_time','-l':'cli_level','--level-key':'cli_level',
        '--map-level':'map_levels','-x':'excluded','--excluded-value':'excluded',
        '-f':'filter_expr','--filter':'filter_expr','--main-line-format':'main_fmt',
        '--additional-value-format':'add_fmt','-c':'context_key','--context-key':'context_key',
        '-F':'placeholder_format','--placeholder-format':'placeholder_format'
    }
    flags={'-d':'dump_all','--dump-all':'dump_all','-p':'with_prefix','--with-prefix':'with_prefix',
           '--print-lua':'print_lua','--no-implicit-filter-return-statement':'no_implicit',
           '-s':'substitute','--substitute':'substitute'}
    while i < len(argv):
        a=argv[i]
        if a=='--':
            pos += argv[i+1:]; break
        if a in ('-h','--help'):
            sys.stdout.write(HELP_TEXT); sys.exit(0)
        if a in ('-V','--version'):
            sys.stdout.write('fblog 4.17.0\n'); sys.exit(0)
        if a.startswith('--') and '=' in a:
            opt,val=a.split('=',1)
            if opt in need:
                target=need[opt]
                if target=='map_levels' and '=' not in val:
                    sys.stderr.write(f"error: invalid value '{val}' for '--map-level <from=to>': missing '='\n\nFor more information, try '--help'.\n")
                    sys.exit(2)
                cur=getattr(o,target)
                if isinstance(cur,list): cur.append(val)
                else: setattr(o,target,val)
                i+=1; continue
        if a in flags:
            setattr(o,flags[a],True); i+=1; continue
        if a in need:
            if i+1>=len(argv):
                sys.exit(clap_err(f"a value is required for '{a}' but none was supplied"))
            val=argv[i+1]; target=need[a]
            if target=='map_levels' and '=' not in val:
                sys.stderr.write(f"error: invalid value '{val}' for '--map-level <from=to>': missing '='\n\nFor more information, try '--help'.\n")
                sys.exit(2)
            cur=getattr(o,target)
            if isinstance(cur,list): cur.append(val)
            else: setattr(o,target,val)
            i+=2; continue
        if a.startswith('-') and a!='-':
            sys.exit(clap_err(f"unexpected argument '{a}' found", f"to pass '{a}' as a value, use '-- {a}'" if a.startswith('--') else None))
        pos.append(a); i+=1
    if len(pos)>1:
        sys.exit(clap_err(f"unexpected argument '{pos[1]}' found"))
    if pos: o.input=pos[0]
    if o.excluded: o.dump_all=True
    return o

# ---------- config ----------
def unquote(s):
    s=s.strip()
    if len(s)>=2 and s[0]=='"' and s[-1]=='"':
        try: return json.loads(s)
        except Exception: return s[1:-1]
    return s

def parse_array(s):
    try:
        # The shipped configuration uses TOML arrays of strings; JSON accepts it.
        return json.loads(s)
    except Exception:
        return [unquote(x.strip()) for x in s.strip()[1:-1].split(',') if x.strip()]

def load_config_file(path, explicit=False):
    cvals={}; level_map={}; section=None
    try:
        data=open(path,'r',encoding='utf-8').read().splitlines()
    except Exception:
        if explicit:
            sys.stderr.write("\nthread 'main' (%d) panicked at src/main.rs:35:50:\nCould not load config file.\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n" % os.getpid())
            sys.exit(101)
        return None
    for raw in data:
        line=raw.strip()
        if not line or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            section=line[1:-1].strip(); continue
        if '=' not in line: continue
        key,val=line.split('=',1); key=key.strip(); val=val.strip()
        # crude comment removal outside common quoted strings
        if section=='level_map':
            level_map[unquote(key)] = unquote(val)
        else:
            if val.startswith('['): cvals[key]=parse_array(val)
            else: cvals[key]=unquote(val)
    if level_map: cvals['level_map']=level_map
    return cvals

def find_config(o):
    if o.config_file: return load_config_file(o.config_file, True)
    paths=[]
    xdg=os.environ.get('XDG_CONFIG_HOME')
    if xdg: paths.append(os.path.join(xdg,'fblog.toml'))
    home=os.environ.get('HOME')
    if home: paths.append(os.path.join(home,'.config','fblog.toml'))
    for p in paths:
        if os.path.exists(p):
            return load_config_file(p, False)
    return None

def build_config(o):
    c=Config(); vals=find_config(o)
    if vals:
        for k,v in vals.items():
            if k=='message_keys': c.message_keys=list(v)
            elif k=='time_keys': c.time_keys=list(v)
            elif k=='dump_all_exclude': c.dump_all_exclude=list(v)
            elif k=='always_print_fields': c.always_print_fields=list(v)
            elif k=='level_keys': c.level_keys=list(v)
            elif k=='main_line_format': c.main_line_format=str(v)
            elif k=='additional_value_format': c.additional_value_format=str(v)
            elif k=='level_map': c.level_map=dict(v)
    if o.main_fmt is not None: c.main_line_format=o.main_fmt
    if o.add_fmt is not None: c.additional_value_format=o.add_fmt
    # Command line detection keys are tried before configured/default keys.
    c.message_keys=list(o.cli_msg)+c.message_keys
    c.time_keys=list(o.cli_time)+c.time_keys
    c.level_keys=list(o.cli_level)+c.level_keys
    for m in o.map_levels:
        f,t=m.split('=',1); c.level_map[f]=t
    return c

# ---------- JSON/path/value handling ----------
def sanitize(k):
    s=re.sub(r'[^A-Za-z0-9_]', '_', str(k))
    s=re.sub(r'_+', '_', s).strip('_')
    if not s: s='_'
    if s[0].isdigit(): s='_'+s
    return s

def parse_segment(seg):
    seg=seg.strip(); m=re.match(r'^([^\[]*)(.*)$', seg)
    key=m.group(1).strip(); rest=m.group(2)
    idxs=[int(x) for x in re.findall(r'\[(-?\d+)\]', rest)]
    return key, idxs

def get_path(obj, path):
    cur=obj
    parts=[p.strip() for p in str(path).split(' > ')]
    for part in parts:
        if part=='': continue
        key,idxs=parse_segment(part)
        if key:
            if isinstance(cur,dict) and key in cur: cur=cur[key]
            else: return None
        for idx in idxs:
            if isinstance(cur,list) and 0 <= idx < len(cur): cur=cur[idx]
            else: return None
    return cur

def is_scalar(v): return v is None or isinstance(v,(str,int,float,bool))

def plain_value(v):
    if v is None: return 'null'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,(int,float)): return str(v)
    if isinstance(v,str): return v
    return ''

def additional_value(v, path):
    if v is None: return None
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,(int,float)): return str(v)
    if isinstance(v,str):
        if '[' in path:
            return json.dumps(v, ensure_ascii=False)
        return v
    return None

def flatten(obj, prefix='', parent_was_array=False):
    out=[]
    if isinstance(obj,dict):
        for k in sorted(obj.keys(), key=str):
            newp = str(k) if not prefix else prefix+' > '+str(k)
            out += flatten(obj[k], newp, False)
    elif isinstance(obj,list):
        base=1 if parent_was_array else 0
        for i,v in enumerate(obj):
            newp = (prefix if prefix else '') + f'[{i+base}]'
            out += flatten(v, newp, True)
    else:
        val=additional_value(obj, prefix)
        if val is not None: out.append((prefix,val))
    return out

def expand_additional(obj, path):
    v=get_path(obj,path)
    if v is None: return []
    if isinstance(v,(dict,list)):
        return flatten(v, path, False)
    val=additional_value(v,path)
    return [(path,val)] if val is not None else []

def detect(keys,obj):
    for k in keys:
        v=get_path(obj,k)
        if v is not None: return v
    return None

def format_timestamp(v):
    if v is None: return ''
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int):
        sec = v/1000.0 if abs(v) >= 100000000000 else v
        try: return datetime.datetime.utcfromtimestamp(sec).strftime('%Y-%m-%dT%H:%M:%S')
        except Exception: return str(v)
    if isinstance(v,str) and re.fullmatch(r'\d+', v):
        try:
            n=int(v); sec=n/1000.0 if len(v)>10 or abs(n)>=100000000000 else n
            return datetime.datetime.utcfromtimestamp(sec).strftime('%Y-%m-%dT%H:%M:%S')
        except Exception: return v
    return plain_value(v)

# ---------- formatting ----------
class RenderError(Exception):
    def __init__(self, helper, col=1): self.helper=helper; self.col=col

def split_first(s):
    s=s.strip(); depth=0
    for i,ch in enumerate(s):
        if ch=='(': depth+=1
        elif ch==')': depth-=1
        elif ch.isspace() and depth==0:
            return s[:i], s[i:].strip()
    return s,''

def strip_outer(s):
    s=s.strip()
    while s.startswith('(') and s.endswith(')'):
        depth=0; ok=True
        for i,ch in enumerate(s):
            if ch=='(': depth+=1
            elif ch==')':
                depth-=1
                if depth==0 and i != len(s)-1:
                    ok=False; break
        if ok: s=s[1:-1].strip()
        else: break
    return s

def eval_fmt_expr(expr, ctx):
    expr=strip_outer(expr)
    if not expr: return ''
    # function(arg) form
    m=re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)$', expr)
    if m:
        func=m.group(1); rest=m.group(2).strip()
        return apply_func(func, rest, ctx)
    first, rest=split_first(expr)
    funcs={'bold','cyan','uppercase','fixed_size','min_size','color_rgb','level_style'}
    if rest and first in funcs:
        return apply_func(first, rest, ctx)
    if rest and first not in funcs:
        raise RenderError(first)
    val=ctx.get(expr,'')
    return plain_value(val) if is_scalar(val) else ''

def take_word(s):
    s=s.strip(); m=re.match(r'^(\S+)(?:\s+(.*))?$', s, re.S)
    return (m.group(1), m.group(2) or '') if m else ('','')

def apply_func(func, rest, ctx):
    if func=='bold': return bold(eval_fmt_expr(rest,ctx))
    if func=='cyan': return fg('36', eval_fmt_expr(rest,ctx))
    if func=='uppercase': return eval_fmt_expr(rest,ctx).upper()
    if func=='level_style': return level_style_text(eval_fmt_expr(rest,ctx), ctx.get('fblog_level','unknown'))
    if func in ('fixed_size','min_size'):
        w, rem=take_word(rest)
        try: n=int(w)
        except Exception: n=0
        s=eval_fmt_expr(rem,ctx)
        if func=='fixed_size':
            if len(s)>n: s=s[:n]
            return s.rjust(n)
        return s.rjust(n) if len(s)<n else s
    if func=='color_rgb':
        r, rest=take_word(rest); g, rest=take_word(rest); b, rest=take_word(rest)
        return rgb(r,g,b,eval_fmt_expr(rest,ctx))
    raise RenderError(func)

def render_template(tpl, ctx, name='main_line'):
    def if_repl(m):
        var=m.group(1).strip(); body=m.group(2)
        v=ctx.get(var)
        return body if v else ''
    s=re.sub(r'\{\{#if\s+([^}]+)\}\}(.*?)\{\{/if\}\}', if_repl, tpl, flags=re.S)
    res=[]; last=0
    for m in re.finditer(r'\{\{(.*?)\}\}', s, flags=re.S):
        res.append(s[last:m.start()])
        expr=m.group(1).strip()
        try:
            res.append(eval_fmt_expr(expr, ctx))
        except RenderError as e:
            col=m.start()+1 if e.col==1 else e.col
            raise RenderError(e.helper,col)
        last=m.end()
    res.append(s[last:])
    return ''.join(res)

# ---------- substitution ----------
def colored_sub_value(v):
    if isinstance(v,str): return fg('1;33', v)
    if isinstance(v,bool): return fg('1;32' if v else '1;31', 'true' if v else 'false')
    if isinstance(v,(int,float)): return fg('1;36', str(v))
    if v is None: return bold('null')
    if isinstance(v,list):
        parts=[dim('[')]
        for i,x in enumerate(v):
            if i: parts.append(dim(', '))
            parts.append(colored_sub_value(x))
        parts.append(dim(']')); return ''.join(parts)
    if isinstance(v,dict):
        parts=[dim('{')]
        first=True
        for k in sorted(v.keys(), key=str):
            if not first: parts.append(dim(', '))
            first=False
            parts.append(fg('35', str(k))); parts.append(dim(': ')); parts.append(colored_sub_value(v[k]))
        parts.append(dim('}')); return ''.join(parts)
