def missing_placeholder(key, fmt):
    idx=fmt.find('key')
    pre=fmt[:idx]; post=fmt[idx+3:]
    return dim(pre)+fg('1;31', key)+dim(post)

def substitute_message(msg, obj, context_key, placeholder_format):
    ctx=get_path(obj, context_key)
    if not isinstance(ctx,(dict,list)): return msg
    idx=placeholder_format.find('key')
    if idx<0: return msg
    pre=placeholder_format[:idx]; post=placeholder_format[idx+3:]
    pattern=re.escape(pre)+r'(.+?)'+re.escape(post)
    def repl(m):
        key=m.group(1)
        found=False; val=None
        if isinstance(ctx,dict) and key in ctx:
            found=True; val=ctx[key]
        elif isinstance(ctx,list):
            try:
                n=int(key)
                if 0 <= n < len(ctx): found=True; val=ctx[n]
            except Exception: pass
        if not found: return missing_placeholder(key, placeholder_format)
        return colored_sub_value(val)
    return re.sub(pattern, repl, msg)

# ---------- Lua-ish filter/debug ----------
class NilDict(dict):
    def __missing__(self,k): return None
class LuaString:
    @staticmethod
    def find(s, pat):
        if s is None: return None
        try:
            m=re.search(str(pat), str(s), re.S)
            return (m.start()+1) if m else None
        except Exception:
            return None
class LuaTable:
    def __init__(self,v): self.v=v
    def __getattr__(self,k):
        if isinstance(self.v,dict) and k in self.v: return lua_wrap(self.v[k])
        return None
    def __getitem__(self,k):
        if isinstance(self.v,list) and isinstance(k,int):
            idx=k-1
            return lua_wrap(self.v[idx]) if 0 <= idx < len(self.v) else None
        if isinstance(self.v,dict): return lua_wrap(self.v.get(k))
        return None

def lua_wrap(v):
    if isinstance(v,(dict,list)): return LuaTable(v)
    return v

def make_lua_env(obj):
    env=NilDict({'string':LuaString(), 'nil':None, 'true':True, 'false':False})
    for k,v in obj.items(): env[sanitize(k)] = lua_wrap(v)
    return env

def translate_lua(expr):
    s=expr.strip()
    s=re.sub(r'\bnil\b','None',s)
    s=re.sub(r'\btrue\b','True',s, flags=re.I)
    s=re.sub(r'\bfalse\b','False',s, flags=re.I)
    s=s.replace('~=','!=')
    s=s.replace('string.find','string.find')
    return s

def apply_filter(expr, obj, no_implicit):
    if expr is None: return True
    e=expr.strip()
    if not no_implicit and e.startswith('return'):
        print(f"{fg('31','Failed to apply filter expression')}: 'SyntaxError {{ message: \"src/filter.rs:23:1: unexpected symbol near 'return'\", incomplete_input: false }}'")
        return False
    if no_implicit and e.startswith('return'):
        e=e[6:].strip()
    try:
        return bool(eval(translate_lua(e), {'__builtins__':{}}, make_lua_env(obj)))
    except Exception as ex:
        print(f"{fg('31','Failed to apply filter expression')}: '{type(ex).__name__}: {ex}'")
        return False

def lua_repr(v):
    if isinstance(v,str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,(int,float)): return str(v)
    if v is None: return '"unsupported"'
    if isinstance(v,list): return '{' + ', '.join(lua_repr(x) for x in v) + '}'
    if isinstance(v,dict):
        return '{' + ', '.join(f'{sanitize(k)} = {lua_repr(v[k])}' for k in sorted(v.keys(), key=str)) + '}'
    return '"unsupported"'

def print_lua_init(obj):
    for k in sorted(obj.keys(), key=lambda x: sanitize(x)):
        print(f'{sanitize(k)} = {lua_repr(obj[k])}')

# ---------- main processing ----------
def context_for(obj, cfg, prefix, opts):
    msgv=detect(cfg.message_keys, obj)
    message=plain_value(msgv) if is_scalar(msgv) else ''
    if opts.substitute and isinstance(message,str):
        message=substitute_message(message, obj, opts.context_key, opts.placeholder_format)
    tv=detect(cfg.time_keys, obj)
    timestamp=format_timestamp(tv)
    lv=detect(cfg.level_keys, obj)
    level=plain_value(lv) if lv is not None and is_scalar(lv) else 'unknown'
    if level in cfg.level_map: level=cfg.level_map[level]
    ctx={}
    for k,v in obj.items(): ctx[sanitize(k)] = plain_value(v) if is_scalar(v) else v
    ctx.update({'fblog_message':message,'fblog_timestamp':timestamp,'fblog_level':level,'fblog_prefix':prefix or ''})
    # Raw names are also convenient in templates.
    if 'message' not in ctx: ctx['message']=message
