        try:
            n=int(v); sec=n/1000.0 if len(v)>10 or abs(n)>=100000000000 else n
            return datetime.datetime.utcfromtimestamp(sec).strftime('%Y-%m-%dT%H:%M:%S')
        except Exception: return v
    return plain_value(v)

# ---------- formatting ----------
class RenderError(Exception):
    def __init__(self, helper, col=1): self.helper=helper; self.col=col

def split_first(s):
    s=s.strip(); depth=0
    for i,ch in enumerate(s):
        if ch=='(': depth+=1
        elif ch==')': depth-=1
        elif ch.isspace() and depth==0:
            return s[:i], s[i:].strip()
    return s,''

def strip_outer(s):
    s=s.strip()
    while s.startswith('(') and s.endswith(')'):
        depth=0; ok=True
        for i,ch in enumerate(s):
            if ch=='(': depth+=1
            elif ch==')':
                depth-=1
                if depth==0 and i != len(s)-1:
                    ok=False; break
        if ok: s=s[1:-1].strip()
        else: break
    return s

def eval_fmt_expr(expr, ctx):
    expr=strip_outer(expr)
    if not expr: return ''
    # function(arg) form
    m=re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)$', expr)
    if m:
        func=m.group(1); rest=m.group(2).strip()
        return apply_func(func, rest, ctx)
    first, rest=split_first(expr)
    funcs={'bold','cyan','uppercase','fixed_size','min_size','color_rgb','level_style'}
    if rest and first in funcs:
        return apply_func(first, rest, ctx)
    if rest and first not in funcs:
        raise RenderError(first)
    val=ctx.get(expr,'')
    return plain_value(val) if is_scalar(val) else ''

def take_word(s):
    s=s.strip(); m=re.match(r'^(\S+)(?:\s+(.*))?$', s, re.S)
    return (m.group(1), m.group(2) or '') if m else ('','')

def apply_func(func, rest, ctx):
    if func=='bold': return bold(eval_fmt_expr(rest,ctx))
    if func=='cyan': return fg('36', eval_fmt_expr(rest,ctx))
    if func=='uppercase': return eval_fmt_expr(rest,ctx).upper()
    if func=='level_style': return level_style_text(eval_fmt_expr(rest,ctx), ctx.get('fblog_level','unknown'))
    if func in ('fixed_size','min_size'):
        w, rem=take_word(rest)
        try: n=int(w)
        except Exception: n=0
        s=eval_fmt_expr(rem,ctx)
        if func=='fixed_size':
            if len(s)>n: s=s[:n]
            return s.rjust(n)
        return s.rjust(n) if len(s)<n else s
    if func=='color_rgb':
        r, rest=take_word(rest); g, rest=take_word(rest); b, rest=take_word(rest)
        return rgb(r,g,b,eval_fmt_expr(rest,ctx))
    raise RenderError(func)

def render_template(tpl, ctx, name='main_line'):
    def if_repl(m):
        var=m.group(1).strip(); body=m.group(2)
        v=ctx.get(var)
        return body if v else ''
    s=re.sub(r'\{\{#if\s+([^}]+)\}\}(.*?)\{\{/if\}\}', if_repl, tpl, flags=re.S)
    res=[]; last=0
    for m in re.finditer(r'\{\{(.*?)\}\}', s, flags=re.S):
        res.append(s[last:m.start()])
        expr=m.group(1).strip()
        try:
            res.append(eval_fmt_expr(expr, ctx))
        except RenderError as e:
            col=m.start()+1 if e.col==1 else e.col
            raise RenderError(e.helper,col)
        last=m.end()
    res.append(s[last:])
    return ''.join(res)

# ---------- substitution ----------
def colored_sub_value(v):
    if isinstance(v,str): return fg('1;33', v)
    if isinstance(v,bool): return fg('1;32' if v else '1;31', 'true' if v else 'false')
    if isinstance(v,(int,float)): return fg('1;36', str(v))
    if v is None: return bold('null')
    if isinstance(v,list):
        parts=[dim('[')]
        for i,x in enumerate(v):
            if i: parts.append(dim(', '))
            parts.append(colored_sub_value(x))
        parts.append(dim(']')); return ''.join(parts)
    if isinstance(v,dict):
        parts=[dim('{')]
        first=True
        for k in sorted(v.keys(), key=str):
            if not first: parts.append(dim(', '))
            first=False
            parts.append(fg('35', str(k))); parts.append(dim(': ')); parts.append(colored_sub_value(v[k]))
        parts.append(dim('}')); return ''.join(parts)
    return str(v)

def missing_placeholder(key, fmt):
    idx=fmt.find('key')
    pre=fmt[:idx]; post=fmt[idx+3:]
    return dim(pre)+fg('1;31', key)+dim(post)

def substitute_message(msg, obj, context_key, placeholder_format):
    ctx=get_path(obj, context_key)
    if not isinstance(ctx,(dict,list)): return msg
    idx=placeholder_format.find('key')
    if idx<0: return msg
    pre=placeholder_format[:idx]; post=placeholder_format[idx+3:]
    pattern=re.escape(pre)+r'(.+?)'+re.escape(post)
    def repl(m):
        key=m.group(1)
        found=False; val=None
        if isinstance(ctx,dict) and key in ctx:
            found=True; val=ctx[key]
        elif isinstance(ctx,list):
            try:
                n=int(key)
                if 0 <= n < len(ctx): found=True; val=ctx[n]
            except Exception: pass
        if not found: return missing_placeholder(key, placeholder_format)
        return colored_sub_value(val)
    return re.sub(pattern, repl, msg)

# ---------- Lua-ish filter/debug ----------
class NilDict(dict):
    def __missing__(self,k): return None
class LuaString:
    @staticmethod
    def find(s, pat):
        if s is None: return None
        try:
            m=re.search(str(pat), str(s), re.S)
            return (m.start()+1) if m else None
        except Exception:
            return None
class LuaTable:
    def __init__(self,v): self.v=v
    def __getattr__(self,k):
        if isinstance(self.v,dict) and k in self.v: return lua_wrap(self.v[k])
        return None
    def __getitem__(self,k):
        if isinstance(self.v,list) and isinstance(k,int):
            idx=k-1
            return lua_wrap(self.v[idx]) if 0 <= idx < len(self.v) else None
        if isinstance(self.v,dict): return lua_wrap(self.v.get(k))
        return None

def lua_wrap(v):
    if isinstance(v,(dict,list)): return LuaTable(v)
    return v

def make_lua_env(obj):
    env=NilDict({'string':LuaString(), 'nil':None, 'true':True, 'false':False})
    for k,v in obj.items(): env[sanitize(k)] = lua_wrap(v)
    return env

def translate_lua(expr):
    s=expr.strip()
    s=re.sub(r'\bnil\b','None',s)
    s=re.sub(r'\btrue\b','True',s, flags=re.I)
    s=re.sub(r'\bfalse\b','False',s, flags=re.I)
    s=s.replace('~=','!=')
    s=s.replace('string.find','string.find')
    return s

def apply_filter(expr, obj, no_implicit):
    if expr is None: return True
    e=expr.strip()
    if not no_implicit and e.startswith('return'):
        print(f"{fg('31','Failed to apply filter expression')}: 'SyntaxError {{ message: \"src/filter.rs:23:1: unexpected symbol near 'return'\", incomplete_input: false }}'")
        return False
    if no_implicit and e.startswith('return'):
        e=e[6:].strip()
    try:
        return bool(eval(translate_lua(e), {'__builtins__':{}}, make_lua_env(obj)))
    except Exception as ex:
        print(f"{fg('31','Failed to apply filter expression')}: '{type(ex).__name__}: {ex}'")
        return False

def lua_repr(v):
    if isinstance(v,str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,(int,float)): return str(v)
    if v is None: return '"unsupported"'
    if isinstance(v,list): return '{' + ', '.join(lua_repr(x) for x in v) + '}'
    if isinstance(v,dict):
        return '{' + ', '.join(f'{sanitize(k)} = {lua_repr(v[k])}' for k in sorted(v.keys(), key=str)) + '}'
    return '"unsupported"'

def print_lua_init(obj):
    for k in sorted(obj.keys(), key=lambda x: sanitize(x)):
        print(f'{sanitize(k)} = {lua_repr(obj[k])}')

# ---------- main processing ----------
def context_for(obj, cfg, prefix, opts):
    msgv=detect(cfg.message_keys, obj)
    message=plain_value(msgv) if is_scalar(msgv) else ''
    if opts.substitute and isinstance(message,str):
        message=substitute_message(message, obj, opts.context_key, opts.placeholder_format)
    tv=detect(cfg.time_keys, obj)
    timestamp=format_timestamp(tv)
    lv=detect(cfg.level_keys, obj)
    level=plain_value(lv) if lv is not None and is_scalar(lv) else 'unknown'
    if level in cfg.level_map: level=cfg.level_map[level]
    ctx={}
    for k,v in obj.items(): ctx[sanitize(k)] = plain_value(v) if is_scalar(v) else v
    ctx.update({'fblog_message':message,'fblog_timestamp':timestamp,'fblog_level':level,'fblog_prefix':prefix or ''})
    # Raw names are also convenient in templates.
    if 'message' not in ctx: ctx['message']=message
    return ctx

def process_line(line, cfg, opts):
    orig=line
    prefix=''; text=line
    if opts.with_prefix:
        idx=line.find('{')
        if idx>=0:
            prefix=line[:idx].strip(); text=line[idx:]
    try:
        obj=json.loads(text)
    except Exception:
        print(f'{orange_prefix()} {orig}')
        return
    if not isinstance(obj,dict):
        print(f'{orange_prefix()} {orig}')
        return
    if opts.print_lua: print_lua_init(obj)
    if not apply_filter(opts.filter_expr, obj, opts.no_implicit): return
    ctx=context_for(obj,cfg,prefix,opts)
    try:
        main=render_template(cfg.main_line_format, ctx, 'main_line')
    except RenderError as e:
        print(f'{red_prefix()} Failed to process line: Error rendering "main_line" line 1, col {e.col}: Helper not found {e.helper}')
        return
    print(main)
    add_paths=[]
    if opts.dump_all:
        excludes=set(cfg.dump_all_exclude + opts.excluded)
        for p,v in flatten(obj):
            if p not in excludes: add_paths.append((p,v))
    else:
        paths=list(cfg.always_print_fields)+list(opts.additional)
        for p in paths: add_paths.extend(expand_additional(obj,p))
    for k,v in add_paths:
        actx={'key':k,'value':v}
        try:
            print(render_template(cfg.additional_value_format, actx, 'additional_value'))
        except RenderError as e:
            print(f'{red_prefix()} Failed to process line: Error rendering "additional_value" line 1, col {e.col}: Helper not found {e.helper}')

def iter_input(path):
    if path=='-':
        data=sys.stdin.buffer.read().splitlines()
    else:
        try:
            data=open(path,'rb').read().splitlines()
        except Exception:
            sys.stderr.write("\nthread 'main' (%d) panicked at src/main.rs:105:68:\nCan't open file: %s\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n" % (os.getpid(), path))
            sys.exit(101)
    for b in data:
        try:
            yield b.decode('utf-8')
        except UnicodeDecodeError:
            print(f'{red_prefix()} Could not read line: stream did not contain valid UTF-8')

def main(argv):
    opts=parse_args(argv)
    cfg=build_config(opts)
    for line in iter_input(opts.input):
        process_line(line,cfg,opts)

if __name__=='__main__':
    main(sys.argv[1:])
